interface Base { id: string; items: Item[] }

interface PedidoBorrador   extends Base { estado: 'borrador' }
interface PedidoPagado     extends Base { estado: 'pagado'; pago: Pago; pagadoEn: Date }
interface PedidoEnviado    extends Base { estado: 'enviado'; pago: Pago; seguimiento: string }
interface PedidoEntregado  extends Base { estado: 'entregado'; entregadoEn: Date }
interface PedidoCancelado  extends Base { estado: 'cancelado'; motivo: string }

type Pedido =
  | PedidoBorrador | PedidoPagado | PedidoEnviado
  | PedidoEntregado | PedidoCancelado;

// Las transiciones válidas viven en las firmas.
function pagar(p: PedidoBorrador, pago: Pago): PedidoPagado {
  return { ...p, estado: 'pagado', pago, pagadoEn: new Date() };
}

function enviar(p: PedidoPagado, seguimiento: string): PedidoEnviado {
  return { ...p, estado: 'enviado', seguimiento };
}

function entregar(p: PedidoEnviado): PedidoEntregado {
  return { ...p, estado: 'entregado', entregadoEn: new Date() };
}

// Solo se puede cancelar lo que aún no salió.
function cancelar(p: PedidoBorrador | PedidoPagado, motivo: string): PedidoCancelado {
  return { ...p, estado: 'cancelado', motivo };
}

// const x = enviar(pedidoCancelado, 'ABC');   // no compila

// El puente con el mundo dinámico: estrechar, no asertar.
function accionesDisponibles(p: Pedido): string[] {
  switch (p.estado) {
    case 'borrador':  return ['pagar', 'cancelar'];
    case 'pagado':    return ['enviar', 'cancelar'];
    case 'enviado':   return ['entregar'];
    case 'entregado':
    case 'cancelado': return [];
  }
}

function manejar(p: Pedido, pago: Pago): Pedido {
  switch (p.estado) {
    case 'borrador': return pagar(p, pago);      // p es PedidoBorrador aquí
    case 'pagado':   return enviar(p, 'ABC');    // p es PedidoPagado aquí
    default:         return p;
  }
}
