// Extensible por declaration merging desde otros módulos.
export interface Eventos {
  'usuario:creado': [usuario: Usuario];
  'pedido:pagado': [pedidoId: string, total: number];
  'app:cerrada': [];
}

type Listener<K extends keyof Eventos> = (...args: Eventos[K]) => void;

export class Emisor {
  // any encapsulado: la API pública sigue siendo segura.
  #listeners = new Map<keyof Eventos, Set<(...a: any[]) => void>>();

  on<K extends keyof Eventos>(evento: K, fn: Listener<K>): () => void {
    if (!this.#listeners.has(evento)) this.#listeners.set(evento, new Set());
    this.#listeners.get(evento)!.add(fn);
    return () => this.off(evento, fn);
  }

  once<K extends keyof Eventos>(evento: K, fn: Listener<K>): () => void {
    const envoltorio = ((...args: Eventos[K]) => {
      this.off(evento, envoltorio);   // antes de invocar, por si lanza
      fn(...args);
    }) as Listener<K>;
    return this.on(evento, envoltorio);
  }

  off<K extends keyof Eventos>(evento: K, fn: Listener<K>): void {
    const set = this.#listeners.get(evento);
    if (!set) return;
    set.delete(fn);
    if (set.size === 0) this.#listeners.delete(evento);
  }

  emit<K extends keyof Eventos>(evento: K, ...args: Eventos[K]): void {
    // Copia: un listener puede darse de baja durante la emisión.
    for (const fn of [...(this.#listeners.get(evento) ?? [])]) {
      try {
        fn(...args);
      } catch (e) {
        queueMicrotask(() => { throw e; });   // no tumbar a los demás
      }
    }
  }
}

const bus = new Emisor();
bus.on('pedido:pagado', (id, total) => { });   // id: string, total: number
bus.emit('pedido:pagado', 'p-1', 1999);
