import { z } from 'zod';

// 1. agrupar: genéricos restringidos y acumulador tipado.
export function agrupar<T, K extends keyof T>(
  items: readonly T[],                 // readonly: no vamos a mutarlo
  clave: K & (T[K] extends PropertyKey ? K : never),
): Record<string, T[]> {
  return items.reduce<Record<string, T[]>>((acc, item) => {
    const k = String(item[clave]);
    // Variable local: el compilador sí puede estrechar esto.
    const grupo = acc[k] ?? [];
    grupo.push(item);
    acc[k] = grupo;
    return acc;
  }, {});
}

// 2. cargarConfig: cortar el any justo donde entra.
const Config = z.object({
  puerto: z.number().int().positive().default(3000),
  host: z.string().default('localhost'),
  debug: z.boolean().default(false),
});

export type Config = z.infer<typeof Config>;

export async function cargarConfig(ruta: string): Promise<Config> {
  let texto: string;
  try {
    texto = await fs.readFile(ruta, 'utf8');
  } catch (e) {
    if (e instanceof Error && 'code' in e && e.code === 'ENOENT') {
      return Config.parse({});          // sin fichero: solo defaults
    }
    throw e;
  }

  let crudo: unknown;                   // unknown, no any
  try {
    crudo = JSON.parse(texto);
  } catch {
    throw new Error(`Config inválida en ${ruta}: no es JSON`);
  }

  // Aquí muere el any: a partir de este punto todo está tipado.
  return Config.parse(crudo);
}
